public inherited sharing class OpportunityWinService {
    public static Integer markWon(Set<Id> opportunityIds) {
        if (opportunityIds == null || opportunityIds.isEmpty()) {
            return 0;
        }

        List<Opportunity> opportunities = OpportunitiesSelector.newInstance().selectById(opportunityIds);
        List<Opportunity> oppsToUpdate = new List<Opportunity>();

        for (Opportunity opp : opportunities) {
            if (opp.StageName != 'Closed Won') {
                oppsToUpdate.add(opp);
            }
        }

        if (oppsToUpdate.isEmpty()) {
            return 0;
        }

        fflib_ISObjectUnitOfWork uow = Application.UnitOfWork.newInstance();

        for (Opportunity opp : oppsToUpdate) {
            opp.StageName = 'Closed Won';
            opp.CloseDate = Date.today();
            uow.registerDirty(opp);

            Deal_Won__e event = new Deal_Won__e(
                Opportunity_Id__c = opp.Id,
                Amount__c = opp.Amount
            );
            uow.registerPublishAfterTransactionComplete(event);
        }

        uow.commitWork();

        return oppsToUpdate.size();
    }
}
