        this.caseId = caseId;
    }

    public void execute(QueueableContext context) {
        // Query the case to get its CaseNumber and ContactId
        List<Case> cases = [SELECT Id, CaseNumber, ContactId FROM Case WHERE Id = :this.caseId LIMIT 1];
        if (cases.isEmpty()) {
            return;
        }

        Case c = cases[0];

