export default class StatusListbox extends LightningElement {
    @api label = '';

    _options = [];
    _selectedValue = '';

    activeIndex = 0;
    hasUserMovedActiveIndex = false;

    @api
    get options() {
        return this._options;
    }
    set options(value) {
        this._options = Array.isArray(value) ? value : [];
        if (!this.hasUserMovedActiveIndex) {
