        return this._selectedValue;
    }
    set value(val) {
        this._selectedValue = val;
        this.syncActiveIndexToValue();
        this.hasUserMovedActiveIndex = false;
    }

    syncActiveIndexToValue() {
        if (!this._options || this._options.length === 0) {
            this.activeIndex = 0;
            return;
        }
        const index = this._options.findIndex(opt => opt.value === this._selectedValue);
        if (index !== -1) {
            this.activeIndex = index;
        } else {
            this.activeIndex = 0;
        }
    }

    get activeDescendantId() {
        if (this._options.length > 0 && this.activeIndex >= 0 && this.activeIndex < this._options.length) {
            return `option-${this.activeIndex}`;
        }
        return undefined;
    }

    get formattedOptions() {
        const activeId = this.activeDescendantId;
        return this._options.map((opt, index) => {
            const optId = `option-${index}`;
            const isSelected = opt.value === this._selectedValue;
            const isActive = optId === activeId;

            let cssClass = 'slds-media slds-listbox__option slds-listbox__option_plain';
            if (isSelected) {
                cssClass += ' slds-is-selected';
            }
            if (isActive) {
                cssClass += ' slds-has-focus';
            }

            return {
                value: opt.value,
                label: opt.label,
                id: optId,
                ariaSelected: isSelected ? 'true' : 'false',
                isAriaSelectedTrue: isSelected,
                class: cssClass
            };
        });
    }

    handleKeyDown(event) {
        const key = event.key;
        const maxIndex = this._options.length - 1;
        if (maxIndex < 0) {
            return;
        }

        let preventDefault = false;

        switch (key) {
            case 'ArrowDown':
                if (this.activeIndex < maxIndex) {
                    this.activeIndex++;
                    this.hasUserMovedActiveIndex = true;
                }
                preventDefault = true;
                break;
            case 'ArrowUp':
                if (this.activeIndex > 0) {
                    this.activeIndex--;
                    this.hasUserMovedActiveIndex = true;
                }
                preventDefault = true;
                break;
            case 'Home':
                this.activeIndex = 0;
                this.hasUserMovedActiveIndex = true;
                preventDefault = true;
                break;
            case 'End':
                this.activeIndex = maxIndex;
                this.hasUserMovedActiveIndex = true;
                preventDefault = true;
                break;
            case 'Enter':
            case ' ':
                this.selectOption(this.activeIndex);
                preventDefault = true;
                break;
            default:
                break;
        }

        if (preventDefault) {
            event.preventDefault();
        }
    }

    handleOptionClick(event) {
        const clickedValue = event.currentTarget.dataset.value;
        const index = this._options.findIndex(opt => opt.value === clickedValue);
        if (index !== -1) {
            this.activeIndex = index;
            this.hasUserMovedActiveIndex = true;
            this.selectOption(index);
        }
    }

    selectOption(index) {
        if (index >= 0 && index < this._options.length) {
            const selectedOption = this._options[index];
            if (selectedOption.value !== this._selectedValue) {
                this.dispatchEvent(new CustomEvent('change', {
                    detail: { value: selectedOption.value }
                }));
            }
        }
    }
}
